package org.odk.platform.service;

import org.javarosa.form.api.FormEntryController;
import org.junit.jupiter.api.Test;

import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * End-to-end compatibility tests for form-version-scoped external data in the
 * JavaRosa web runtime. These tests start with the same jr://file-csv reference
 * generated by XLSForm/ODK tooling, then exercise JavaRosa after the runtime
 * preprocessor has resolved the uploaded dataset.
 */
class FormDefinitionExternalDataTest {

    private static final String CITIES_CSV = """
            code,label,country
            kla,Kampala,ug
            jinja,Jinja,ug
            nai,Nairobi,ke
            """;

    private static final String EXTERNAL_DATA_XFORM = """
            <?xml version="1.0" encoding="UTF-8"?>
            <h:html xmlns:h="http://www.w3.org/1999/xhtml"
                    xmlns="http://www.w3.org/2002/xforms"
                    xmlns:jr="http://openrosa.org/javarosa">
                <h:head>
                    <h:title>External Data</h:title>
                    <model>
                        <instance>
                            <data id="external_data" version="1.0">
                                <country/>
                                <city/>
                                <city_label/>
                                <meta><instanceID/></meta>
                            </data>
                        </instance>
                        <instance id="cities" src="jr://file-csv/cities.csv"/>
                        <bind nodeset="/data/country" type="select1"/>
                        <bind nodeset="/data/city" type="select1"/>
                        <bind nodeset="/data/city_label" type="string"
                              calculate="pulldata('cities', 'label', 'code', /data/city)"/>
                    </model>
                </h:head>
                <h:body>
                    <select1 ref="/data/country">
                        <label>Country</label>
                        <item><label>Uganda</label><value>ug</value></item>
                        <item><label>Kenya</label><value>ke</value></item>
                    </select1>
                    <select1 ref="/data/city">
                        <label>City</label>
                        <itemset nodeset="instance('cities')/root/item[country = current()/../country]">
                            <label ref="label"/>
                            <value ref="code"/>
                        </itemset>
                    </select1>
                </h:body>
            </h:html>
            """;

    @Test
    void externalCsv_supportsChoiceFilterAndPulldataCalculate() {
        FormDefinition form = FormDefinition.createNew(
                EXTERNAL_DATA_XFORM,
                "external-data-test",
                Map.of("cities.csv", CITIES_CSV.getBytes(StandardCharsets.UTF_8)));

        assertTrue(form.getCompatibilityWarnings().isEmpty(), form.getCompatibilityWarnings().toString());
        assertTrue(form.getFormDef().getNonMainInstance("cities") != null);

        assertEquals(FormEntryController.EVENT_QUESTION, form.stepToNextEvent());
        assertEquals("country", form.getCurrentQuestionPath());
        assertEquals(FormEntryController.ANSWER_OK, form.answerQuestion(form.parseAnswer("ug")));

        assertEquals(FormEntryController.EVENT_QUESTION, form.stepToNextEvent());
        assertEquals("city", form.getCurrentQuestionPath());

        List<FormDefinition.SelectChoice> choices = form.getCurrentChoices();
        assertEquals(List.of("kla", "jinja"), choices.stream().map(FormDefinition.SelectChoice::getValue).toList());
        assertEquals(List.of("Kampala", "Jinja"), choices.stream().map(FormDefinition.SelectChoice::getLabel).toList());

        assertEquals(FormEntryController.ANSWER_OK, form.answerQuestion(form.parseAnswer("kla")));
        assertEquals("Kampala", form.evaluateXPath("/data/city_label"));
        assertEquals("Nairobi", form.evaluateXPath("instance('cities')/root/item[code = 'nai']/label"));
    }

    @Test
    void uploadedXmlInstance_isAvailableToJavaRosaInstanceLookups() {
        String xmlXform = """
                <?xml version="1.0" encoding="UTF-8"?>
                <h:html xmlns:h="http://www.w3.org/1999/xhtml"
                        xmlns="http://www.w3.org/2002/xforms">
                    <h:head>
                        <h:title>XML External Instance</h:title>
                        <model>
                            <instance><data id="xml_external"><facility_label/><meta><instanceID/></meta></data></instance>
                            <instance id="facilities" src="jr://file-xml/facilities.xml"/>
                            <bind nodeset="/data/facility_label" type="string"
                                  calculate="instance('facilities')/root/item[id = 'f2']/label"/>
                        </model>
                    </h:head>
                    <h:body/>
                </h:html>
                """;
        byte[] facilities = """
                <root>
                    <item><id>f1</id><label>Clinic A</label></item>
                    <item><id>f2</id><label>Clinic B</label></item>
                </root>
                """.getBytes(StandardCharsets.UTF_8);

        FormDefinition form = FormDefinition.createNew(
                xmlXform,
                "external-xml-test",
                Map.of("facilities.xml", facilities));

        assertTrue(form.getCompatibilityWarnings().isEmpty(), form.getCompatibilityWarnings().toString());
        assertEquals("Clinic B", form.evaluateXPath("/data/facility_label"));
        assertEquals("Clinic A",
                form.evaluateXPath("instance('facilities')/root/item[id = 'f1']/label"));
    }

    @Test
    void missingExternalDataset_isReportedInsteadOfSilentlyIgnored() {
        XFormRuntimePreprocessor.PreparedXForm prepared =
                XFormRuntimePreprocessor.prepare(EXTERNAL_DATA_XFORM, Map.of());

        assertFalse(prepared.warnings().isEmpty());
        assertTrue(prepared.warnings().stream().anyMatch(message -> message.contains("cities.csv")));
    }

    @Test
    void unsupportedFunction_isSurfacedAsCompatibilityWarning() {
        String xform = EXTERNAL_DATA_XFORM.replace(
                "pulldata('cities', 'label', 'code', /data/city)",
                "custom-lookup(/data/city)");

        XFormRuntimePreprocessor.PreparedXForm prepared = XFormRuntimePreprocessor.prepare(
                xform,
                Map.of("cities.csv", CITIES_CSV.getBytes(StandardCharsets.UTF_8)));

        assertTrue(prepared.warnings().stream()
                .anyMatch(message -> message.contains("custom-lookup()")));
    }
}
